public class Solution {
    public int search(int[] nums, int target) {
        int l=0, r=nums.length;  // r должен быть length-1
        while (l<=r) {
            int m = (l+r)/2;
            if (nums[m]==target) return m;  // ArrayIndexOutOfBounds когда m=length
            if (nums[m]<target) l=m+1; else r=m-1;
        }
        return -1;
    }
}

public class Solution {
    public int climbStairs(int n) {
        int[] dp = new int[n];  // не учитывает n=0 → отрицательный размер
        dp[0]=1; dp[1]=2;
        for (int i=2; i<n; i++) dp[i]=dp[i-1]+dp[i-2];
        return dp[n-1];
    }
}

public class Solution {
    public int[] countBits(int n) {
        int[] r = new int[n];  // должно быть n+1
        for (int i = 0; i <= n; i++) r[i] = Integer.bitCount(i);
        return r;
    }
}

